using Toki.Caja.Contracts;
using Toki.Fiscal.Contracts;
using Toki.Inventario.Contracts;
using Toki.SharedKernel;

namespace Toki.Ventas.Domain;

public enum NivelPrecio { Detalle, Mayorista }

internal enum EstadoVenta { Completada, Anulada }

internal sealed class Venta
{
    /// <summary>Receipt number shown to people (local, increasing). The fiscal number is <see cref="ENcf"/>.</summary>
    public long Numero { get; set; }
    /// <summary>Generated by the register: retrying the same sale returns the same result (idempotency key).</summary>
    public Guid Id { get; set; }
    public Guid TurnoId { get; set; }
    public Guid CajaId { get; set; }
    public string Caja { get; set; } = "";
    public Guid CajeroId { get; set; }
    public string Cajero { get; set; } = "";
    public Guid? ClienteId { get; set; }
    public string? ClienteNombre { get; set; }
    public string? RncCliente { get; set; }
    public TipoEcf TipoComprobante { get; set; }
    public string ENcf { get; set; } = "";
    public string CodigoSeguridad { get; set; } = "";
    public string UrlQr { get; set; } = "";
    public NivelPrecio Nivel { get; set; }
    public decimal Bruto { get; set; }
    public decimal Descuento { get; set; }
    public decimal Subtotal { get; set; }
    public decimal Itbis { get; set; }
    public decimal Total { get; set; }
    public decimal Cambio { get; set; }
    /// <summary>Cash centavos kept because change is given in whole pesos.</summary>
    public decimal Redondeo { get; set; }
    public EstadoVenta Estado { get; set; }
    /// <summary>Bumped by an atomic update before a void or return reads the sale: it locks the row, so they run one at a time.</summary>
    public int Version { get; set; }
    public DateTime FechaUtc { get; set; }
    public DateTime? AnuladaUtc { get; set; }
    public string? MotivoAnulacion { get; set; }
    public Guid? AnuladaPorId { get; set; }
    public string? ENcfAnulacion { get; set; }
    public Guid? SupervisorId { get; set; }
    public List<LineaVenta> Lineas { get; set; } = [];
    public List<PagoVenta> Pagos { get; set; } = [];
}

internal sealed class LineaVenta
{
    public Guid Id { get; set; }
    public Guid VentaId { get; set; }
    public int Orden { get; set; }
    public Guid ProductoId { get; set; }
    public Guid? PresentacionId { get; set; }
    public Guid CategoriaId { get; set; }
    public string Descripcion { get; set; } = "";
    public UnidadMedida Unidad { get; set; }
    public decimal Cantidad { get; set; }
    /// <summary>Base units per sold unit; inventory moves Cantidad × Factor.</summary>
    public decimal Factor { get; set; }
    public decimal PrecioLista { get; set; }
    public decimal PrecioUnitario { get; set; }
    public decimal Bruto { get; set; }
    public decimal Descuento { get; set; }
    public TasaItbis TasaItbis { get; set; }
    public decimal Itbis { get; set; }
    public decimal Total { get; set; }
    /// <summary>Cost per sold unit at the moment of the sale (historical cost for profit reports).</summary>
    public decimal CostoUnitario { get; set; }
    public string? Nota { get; set; }
    public string? CodigoEtiqueta { get; set; }
    public decimal CantidadDevuelta { get; set; }
}

internal sealed class PagoVenta
{
    public Guid Id { get; set; }
    public Guid VentaId { get; set; }
    public MedioPago Medio { get; set; }
    public decimal Monto { get; set; }
    public decimal? Recibido { get; set; }
    public string? Referencia { get; set; }
}

internal sealed class Devolucion
{
    public Guid Id { get; set; }
    public Guid VentaId { get; set; }
    public Guid TurnoId { get; set; }
    public MedioPago Medio { get; set; }
    public decimal Total { get; set; }
    public decimal Itbis { get; set; }
    public string ENcf { get; set; } = "";
    public string Motivo { get; set; } = "";
    public DateTime FechaUtc { get; set; }
    public Guid UsuarioId { get; set; }
    public Guid? SupervisorId { get; set; }
    public List<LineaDevolucion> Lineas { get; set; } = [];
}

internal sealed class LineaDevolucion
{
    public Guid DevolucionId { get; set; }
    public Guid LineaVentaId { get; set; }
    public decimal Cantidad { get; set; }
    public decimal Total { get; set; }
    public decimal Itbis { get; set; }
    public bool Repuesto { get; set; }
}

/// <summary>A cart parked at a register to serve the next customer; the register stores the draft as JSON.</summary>
internal sealed class VentaEnEspera
{
    public Guid Id { get; set; }
    public Guid TurnoId { get; set; }
    public Guid UsuarioId { get; set; }
    public string Etiqueta { get; set; } = "";
    public string Contenido { get; set; } = "";
    public decimal Total { get; set; }
    public DateTime CreadaUtc { get; set; }
}

internal static class VentasErrors
{
    public static readonly Error VentaNoEncontrada = Error.NotFound("Ventas.VentaNoEncontrada", "La venta no existe.");
    public static readonly Error ProductoNoDisponible = Error.Conflict("Ventas.ProductoNoDisponible", "Un producto de la venta no existe o está desactivado.");
    public static readonly Error YaAnulada = Error.Conflict("Ventas.YaAnulada", "La venta ya está anulada.");
    public static readonly Error FueraDeTurno = Error.Conflict("Ventas.FueraDeTurno", "El turno de esa venta ya cerró. Haga una devolución (nota de crédito).");
    public static readonly Error ConDevoluciones = Error.Conflict("Ventas.ConDevoluciones", "La venta tiene devoluciones; no se puede anular.");
    public static readonly Error CantidadDevolucion = Error.Validation("Ventas.CantidadDevolucion", "No se puede devolver más de lo que se vendió.");
    public static readonly Error EtiquetaRepetida = Error.Conflict("Ventas.EtiquetaRepetida", "Esa etiqueta de balanza ya está en la venta.");
    public static readonly Error MedioNoDisponible = Error.Validation("Ventas.MedioNoDisponible", "Ese medio de pago necesita un cliente con cuenta.");
    public static readonly Error IdRepetido = Error.Conflict("Ventas.IdRepetido", "Ese número de venta ya se usó para otra venta. Vuelva a cobrar.");
    public static readonly Error EtiquetaNoCoincide = Error.Conflict("Ventas.EtiquetaNoCoincide", "La etiqueta de balanza es de otro producto.");
    public static readonly Error RncRequerido = Error.Validation("Ventas.RncRequerido", "Este comprobante necesita el RNC o la cédula del cliente.");

    public static Error MedioExcedido(MedioPago medio, decimal maximo) =>
        Error.Validation("Ventas.MedioExcedido", $"Por {medio} se pueden devolver como máximo RD$ {maximo:N2} (lo que se cobró así).");

    public static Error TotalCambio(decimal total) =>
        Error.Conflict("Ventas.TotalCambio", $"El total cambió a RD$ {total:N2}. Revise la venta antes de cobrar.") with
        {
            Details = new Dictionary<string, string[]> { ["total"] = [total.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture)] },
        };
}
